_ARCHIVE = zipfile.ZipFile(io.BytesIO(base64.b85decode(_EMBEDDED)))
_SOURCES = {n: _ARCHIVE.read(n).decode('utf-8-sig') for n in _ARCHIVE.namelist() if n.endswith('.py')}
_THRESHOLDS = {p: _ARCHIVE.read('threshold_'+p+'.csv').decode('utf-8-sig') for p in ('BUY1','BUY2','BUY3')}
ROOT = Path(__file__).resolve().parent
BASE = ROOT / 'data' / 'marketsentinel_daily'
MARKETS = {'ITALIA':'italy40','EUROPA':'europe40','USA80':'usa80','USA40':'usa40'}

# All scientific Python source is contained in THIS file, loaded into memory.
# No external .py module from the project is read or imported.
class _InternalLoader(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        key = fullname.replace('.', '/') + '.py'
        if fullname == 'operational':
            return importlib.util.spec_from_loader(fullname, self, is_package=True)
        if key in _SOURCES:
            return importlib.util.spec_from_loader(fullname, self)
        return None
    def create_module(self, spec): return None
    def exec_module(self, module):
        if module.__name__ == 'operational':
            module.__path__ = [str(ROOT / 'operational')]
            return
        key = module.__name__.replace('.', '/') + '.py'
        module.__file__ = str(ROOT / key)
        code = _SOURCES[key]
        if key == 'operational/build_usa80_v160_ratings.py':
            # Only replace the source of threshold CSV, never the scoring formula.
            code = code.replace('t = pd.read_csv(path)', 't = pd.read_csv(__import__("io").StringIO(_INTERNAL_THRESHOLDS[phase]))')
            module.__dict__['_INTERNAL_THRESHOLDS'] = _THRESHOLDS
        exec(compile(code, module.__file__, 'exec'), module.__dict__)

_LOADER = _InternalLoader()
if not any(isinstance(x, _InternalLoader) for x in sys.meta_path):
    sys.meta_path.insert(0, _LOADER)

def run_embedded(name):
    key = 'operational/' + name + '.py'
    if key not in _SOURCES: raise RuntimeError('Modulo interno assente: '+key)
    scope = {'__name__':'__main__','__file__':str(ROOT/key),'__package__':'operational'}
    exec(compile(_SOURCES[key], str(ROOT/key), 'exec'), scope)

def last_completed_session():
    """Cutoff prudenziale UTC: non usa mai la giornata UTC corrente."""
    now = dt.datetime.now(dt.timezone.utc)
    return pd.Timestamp(now.date() - dt.timedelta(days=1))


def update_daily_prices(progress):
    """Aggiornamento incrementale DAILY, senza accesso agli archivi DAILY."""
    import time
    import yfinance as yf
    started = time.perf_counter()
    BASE.mkdir(parents=True, exist_ok=True)
    cutoff = last_completed_session()
    ohlcv = ['Open', 'High', 'Low', 'Close', 'Volume']
    market_sizes = {'italy40': 40, 'europe40': 40, 'usa80': 80, 'usa40': 39}
    changed = False
    checked = 0
    total = 199
    for market, prefix in MARKETS.items():
        path = BASE / (prefix + '_daily_master.csv')
        if not path.exists():
            raise FileNotFoundError('Master DAILY mancante: ' + str(path))
        old = pd.read_csv(path, low_memory=False)
        if not {'Ticker', 'Date', *ohlcv}.issubset(old.columns):
            raise ValueError(prefix + ': colonne OHLCV mancanti')
        old['Ticker'] = old['Ticker'].astype(str)
        old['Date'] = pd.to_datetime(old['Date'], errors='coerce', utc=True).dt.tz_localize(None).dt.normalize()
        if old['Date'].isna().any() or old.duplicated(['Ticker', 'Date']).any():
            raise ValueError(prefix + ': date invalide o duplicate')
        tickers = sorted(t for t in old['Ticker'].dropna().unique() if t != 'WBD')
        if len(tickers) != market_sizes[prefix]:
            raise ValueError(f'{prefix}: attesi {market_sizes[prefix]} titoli, trovati {len(tickers)}')
        # Un ticker con storico insufficiente NON può ricevere rating scientifico.
        lengths = old.loc[old['Ticker'] != 'WBD'].groupby('Ticker').size()
        inadequate = lengths[lengths < 100]
        if len(inadequate):
            raise ValueError('Storico DAILY insufficiente in ' + prefix + ': ' +
                             ', '.join(f'{t} ({n} sedute)' for t, n in inadequate.items()) +
                             '. Correggere il master prima di calcolare PHASE/V160.')
        parts = [old.loc[old['Ticker'] != 'WBD'].copy()]
        for ticker in tickers:
            g = old[old['Ticker'] == ticker]
            last = g['Date'].max()
            if last >= cutoff:
                checked += 1
                continue
            begin = (last - pd.Timedelta(days=7)).date().isoformat()
            end = (cutoff + pd.Timedelta(days=1)).date().isoformat()
            try:
                d = yf.download(ticker, start=begin, end=end, interval='1d',
                                auto_adjust=False, progress=False, threads=False, timeout=25)
                if isinstance(d.columns, pd.MultiIndex):
                    if ticker in d.columns.get_level_values(0):
                        d = d[ticker]
                    elif ticker in d.columns.get_level_values(1):
                        d = d.xs(ticker, axis=1, level=1)
                if not d.empty:
                    d = d.reset_index()
                    d['Date'] = pd.to_datetime(d['Date'], utc=True).dt.tz_localize(None).dt.normalize()
                    d['Ticker'] = ticker
                    for col in ohlcv:
                        d[col] = pd.to_numeric(d[col], errors='coerce')
                    d = d[['Ticker', 'Date'] + ohlcv].dropna(subset=ohlcv[:4])
                    d = d[(d['Date'] > last) & (d['Date'] <= cutoff)]
                    if not d.empty:
                        parts.append(d)
                        changed = True
            except Exception as exc:
                raise RuntimeError(f'Yahoo DAILY {ticker}: {exc}') from exc
            checked += 1
            progress.progress(min(.44, .44 * checked / total),
                              text=f'Controllo DAILY {checked}/199 · {ticker}')
        if len(parts) > 1:
            merged = pd.concat(parts, ignore_index=True)
            merged = merged.sort_values(['Ticker', 'Date']).drop_duplicates(['Ticker', 'Date'], keep='last')
            merged['Date'] = merged['Date'].dt.strftime('%Y-%m-%d')
            temp = path.with_suffix('.updating.csv')
            merged.to_csv(temp, index=False)
            temp.replace(path)
    output = BASE / 'marketsentinel_200_phase_nuova.csv'
    needs_calculation = changed or not output.exists()
    progress.progress(.44, text='Archivi DAILY controllati · aggiornamento completato')
    return cutoff, time.perf_counter() - started, needs_calculation


def _calculate_one_market(prefix):
    """Independent scientific pipeline for one market; original algorithms unchanged."""
    import time
    start = time.perf_counter()
    phase = 'update_phase' if prefix == 'italy40' else 'update_phase_' + prefix
    feat = 'update_v160_features' if prefix == 'italy40' else 'update_v160_features_' + prefix
    run_embedded(phase)
    phase_seconds = time.perf_counter() - start
    run_embedded(feat)
    return prefix, phase_seconds, time.perf_counter() - start


def recalculate(progress):
    """Parallel market-independent pipelines, with phase-before-features ordering."""
    import time
    import multiprocessing as mp
    from concurrent.futures import ProcessPoolExecutor, as_completed

    start = time.perf_counter()
    prefixes = list(MARKETS.values())
    results = {}
    # Each market writes distinct phase and feature CSV files. Within each market,
    # canonical PHASE always precedes V160. The final aggregation runs only after all.
    # Two workers limit peak memory while allowing actual multicore execution.
    if 'fork' not in mp.get_all_start_methods():
        raise RuntimeError('Esecuzione parallela richiede Linux/fork (GitHub Codespaces).')
    ctx = mp.get_context('fork')
    with ProcessPoolExecutor(max_workers=2, mp_context=ctx) as pool:
        jobs = {pool.submit(_calculate_one_market, prefix): prefix for prefix in prefixes}
        for future in as_completed(jobs):
            prefix = jobs[future]
            try:
                name, phase_seconds, total_seconds = future.result()
            except Exception as exc:
                for job in jobs: job.cancel()
                raise RuntimeError(f'Calcolo scientifico fallito per {prefix}: {exc}') from exc
            results[name] = (phase_seconds, total_seconds)
            progress.progress(0.44 + 0.45 * len(results) / len(prefixes),
                text=f'PHASE + V160 completati: {len(results)}/4 mercati · ultimo: {name} ({total_seconds:.1f}s)')
    progress.progress(0.92, text='Aggregazione finale PHASE NUOVA e rating V160')
    from operational.run_marketsentinel import main
    main()
    progress.progress(1.0, text=f'PHASE NUOVA e V160 completati in {time.perf_counter()-start:.1f}s')
    return results

def refresh_targets(progress):
    """Target analisti dei 199 ticker: richieste concorrenti e salvataggio atomico."""
    import time
    import yfinance as yf
    from concurrent.futures import ThreadPoolExecutor, as_completed

    started = time.perf_counter()
    p = BASE / 'marketsentinel_200_phase_nuova.csv'
    if not p.exists():
        raise FileNotFoundError(str(p))
    tickers = pd.read_csv(p, usecols=['Ticker'])['Ticker'].dropna().astype(str).tolist()
    if len(tickers) != 199 or len(set(tickers)) != 199:
        raise ValueError('Target: attesi 199 ticker distinti')
    old = BASE / 'marketsentinel_yahoo_targets.csv'
    previous = pd.read_csv(old).set_index('Ticker') if old.exists() else pd.DataFrame()
    prior = {}
    if 'targetMeanPrice' in previous.columns:
        prior = pd.to_numeric(previous['targetMeanPrice'], errors='coerce').to_dict()

    def fetch_one(ticker):
        try:
            info = yf.Ticker(ticker).get_info()
            value = pd.to_numeric(info.get('targetMeanPrice'), errors='coerce')
            if pd.notna(value) and np.isfinite(value) and value > 0:
                return ticker, float(value), 'Yahoo'
        except Exception:
            pass
        value = prior.get(ticker, np.nan)
        return ticker, value, 'cache' if pd.notna(value) else 'assente'

    results = {}
    # Limitiamo a 12 connessioni per ridurre throttling e blocchi Yahoo.
    with ThreadPoolExecutor(max_workers=12) as pool:
        futures = {pool.submit(fetch_one, ticker): ticker for ticker in tickers}
        for i, future in enumerate(as_completed(futures), 1):
            ticker, value, source = future.result()
            results[ticker] = {'Ticker': ticker, 'targetMeanPrice': value, 'target_source': source}
            progress.progress(i / len(tickers), text=f'Target analisti · {i}/199 · {time.perf_counter()-started:.1f}s')
    out = pd.DataFrame([results[t] for t in tickers])
    tmp = old.with_suffix('.updating.csv')
    out.to_csv(tmp, index=False)
    tmp.replace(old)
    return time.perf_counter() - started, int((out['target_source'] == 'Yahoo').sum())

def get_targets():
    p=BASE/'marketsentinel_yahoo_targets.csv'
    if p.exists():
        return pd.read_csv(p)[['Ticker','targetMeanPrice']]
    legacy=ROOT/'data/v40_99_predictive_error_hidden_opportunity/v40_99f_yahoo_current_pt_coverage.csv'
    if legacy.exists():
        d=pd.read_csv(legacy)
        if {'Ticker','mean'}.issubset(d.columns):return d[['Ticker','mean']].rename(columns={'mean':'targetMeanPrice'})
    complete=BASE/'marketsentinel_200_completo.csv'
    if complete.exists():
        d=pd.read_csv(complete)
        for col in ['targetMeanPrice','mean']:
            if col in d.columns:return d[['Ticker',col]].rename(columns={col:'targetMeanPrice'})
    return pd.DataFrame(columns=['Ticker','targetMeanPrice'])

ORDER={'TREND_RIALZISTA':1,'DEBOLEZZA_RIALZISTA':2,'SELL1':3,'SELL2':4,'SELL3':5,'TREND_RIBASSISTA':6,'DEBOLEZZA_RIBASSISTA':7,'INDECISIONE':8}
COLUMNS=['NOME TITOLO','MERCATO','PHASE NUOVA','RATING','RENDIMENTO ATTESO','DATA']

def load_table():
    p=BASE/'marketsentinel_200_phase_nuova.csv'
    if not p.exists():return pd.DataFrame(columns=COLUMNS),None
    d=pd.read_csv(p,low_memory=False)
    if len(d)!=199 or d['Ticker'].nunique()!=199:raise ValueError('Classifica non valida: attesi 199 titoli univoci')
    d=d.merge(get_targets().drop_duplicates('Ticker'),on='Ticker',how='left')
    close=pd.to_numeric(d.get('Close'),errors='coerce')
    mean=pd.to_numeric(d.get('targetMeanPrice'),errors='coerce')
    d['RENDIMENTO ATTESO']=(mean/close-1)*100
    d['RATING']=pd.to_numeric(d['RATING_V160'],errors='coerce').where(d['PHASE_NUOVA'].isin(['BUY1','BUY2','BUY3']))
    d['DATA']=pd.to_datetime(d['Date'],errors='coerce',utc=True).dt.strftime('%d/%m/%Y')
    d=d.rename(columns={'Ticker':'NOME TITOLO','PHASE_NUOVA':'PHASE NUOVA'})
    d['MERCATO']=d['MERCATO'].replace({'USA80':'USA','USA40':'USA'})
    d['_buy']=~d['PHASE NUOVA'].isin(['BUY1','BUY2','BUY3'])
    d['_phase']=d['PHASE NUOVA'].map(ORDER).fillna(9)
    d=d.sort_values(['_buy','RATING','_phase','NOME TITOLO'],ascending=[True,False,True,True],na_position='last')
    return d[COLUMNS].reset_index(drop=True),pd.to_datetime(pd.read_csv(p,usecols=['Date'])['Date'],utc=True).max()

def excel_bytes(frame):
    from openpyxl.styles import Font,PatternFill,Alignment
    from openpyxl.utils import get_column_letter
    buf=io.BytesIO()
    with pd.ExcelWriter(buf,engine='openpyxl') as writer:
        frame.to_excel(writer,index=False,sheet_name='MarketSentinel')
        ws=writer.sheets['MarketSentinel'];ws.freeze_panes='A2';ws.auto_filter.ref=ws.dimensions
        widths=[21,17,28,13,23,16]
        for i,w in enumerate(widths,1):ws.column_dimensions[get_column_letter(i)].width=w
        for cell in ws[1]:
            cell.fill=PatternFill('solid',fgColor='10253D');cell.font=Font(color='FFFFFF',bold=True)
            cell.alignment=Alignment(vertical='center')
        ws.row_dimensions[1].height=28
        for row in ws.iter_rows(min_row=2):
            for cell in row:
                cell.fill=PatternFill('solid',fgColor=('EAF2F8' if cell.row%2==0 else 'FFFFFF'))
            row[3].number_format='0.000'
            row[4].number_format='+0.00" %";-0.00" %";0.00" %"'
    return buf.getvalue()

def _preflight():
    """Verifica statica senza Yahoo, senza calcoli e senza scritture sui CSV."""
    import ast
    required = ['operational/run_marketsentinel.py']
    required += [f'operational/update_phase{suffix}.py' for suffix in ['', '_europe40', '_usa80', '_usa40']]
    required += [f'operational/update_v160_features{suffix}.py' for suffix in ['', '_europe40', '_usa80', '_usa40']]
    missing = [name for name in required if name not in _SOURCES]
    print('Sorgenti incorporati:', len(_SOURCES))
    print('Sorgenti operativi richiesti mancanti:', missing)
    for name in required:
        if name in _SOURCES:
            ast.parse(_SOURCES[name], filename=name)
    print('Sintassi dei sorgenti operativi: OK')
    print('Scritture sui dati: NESSUNA (controllo statico)')
    if missing:
        raise RuntimeError('Preflight non superato')

if __name__ == '__main__' and '--preflight' in sys.argv:
    _preflight()
    sys.exit(0)

